import { error } from "@sveltejs/kit";
import type { PageLoad } from "./$types";

export const load: PageLoad = async ({ params, fetch }) => {
  // add "world" as the root path for the API request, and append the slug if it exists
  const apiPath = "world" + (params.slug ? `/${params.slug}` : "");

  // Fetch the element payload generated by your Bun pipeline
  const res = await fetch(`/api/${apiPath}/elements.json`);

  if (!res.ok) {
    // If the file doesn't exist, SvelteKit will natively show a 404 page
    error(404, "Climbing area or route not found");
  }

  const elementData = await res.json();

  return {
    elementData,
  };
};
